-- M15.07–08, 24 original scenario-based Y1 items based on teacher training theory,
-- Pedagogik qobiliyatlar and inclusive education materials and the M15 topic notes.
-- All new items are authored for this platform, not historical exam question copies.
BEGIN;
DO $m15$
DECLARE r record; v_lesson uuid; v_con uuid; v_sub uuid; v_group text; v_qid uuid; v_oid uuid; v_choices text[]; v_n integer; v_seed text;
BEGIN
 FOR r IN SELECT * FROM (VALUES
(7,1,'O‘qituvchi mavhum tushunchani sodda misollar bilan anglatdi. Qaysi qobiliyat?','Didaktik qobiliyat — materialni tushunarli qilib yetkazish','Akademik qobiliyat — fan bo‘yicha ilmiy bilimni chuqurlashtirish','Perseptiv qobiliyat — o‘quvchi ichki holatini tushunish','Tashkilotchilik qobiliyati — faoliyatni tartibga solish','Murakkab materialni mos tushuntirish didaktik qobiliyatga kiradi','qollash'),
(7,2,'O‘qituvchi o‘quvchining xavotirini yuz ifodasidan sezdi. Qaysi qobiliyat?','Perseptiv qobiliyat — o‘quvchining holatini sezish va tushunish','Akademik qobiliyat — mavzuga oid nazariy bilimlarni kengaytirish','Tashkilotchilik qobiliyati — guruh faoliyatini muvofiqlashtirish','Didaktik qobiliyat — materialni tizimli va sodda tushuntirish','O‘quvchining ichki holatini payqash perseptiv qobiliyat belgisidir','qollash'),
(7,3,'O‘qituvchi fan tadqiqotlarini chuqur biladi. Qaysi qobiliyat kuchli?','Akademik qobiliyat — o‘z fani mazmunini chuqur bilish','Kommunikativ qobiliyat — o‘quvchilar bilan aloqa o‘rnatish','Tashkilotchilik qobiliyati — sinf ishlarini uyushtirish','Perseptiv qobiliyat — bolaning ruhiy holatini payqash','Fan bo‘yicha bilimning chuqurligi akademik qobiliyatdir','bilish'),
(7,4,'O‘qituvchi sinfdagi hamma bilan ishonchli muloqot o‘rnatdi. Qaysi qobiliyat?','Kommunikativ qobiliyat — samarali muloqot va aloqa o‘rnatish','Akademik qobiliyat — ilmiy ma’lumotni chuqur o‘zlashtirish','Didaktik qobiliyat — bilimni sodda tushuntirib yetkazish','Prognostik qobiliyat — kelajakdagi natijani oldindan ko‘rish','Odamlar bilan aloqa o‘rnatish kommunikativ qobiliyat belgisidir','qollash'),
(7,5,'O‘qituvchi dars vaqtini to‘g‘ri taqsimlay olmayapti. Qaysi qobiliyatni rivojlantirish kerak?','Tashkilotchilik qobiliyati — jarayon va guruh faoliyatini boshqarish','Perseptiv qobiliyat — o‘quvchining hissiy holatini anglash','Akademik qobiliyat — fan tushunchalarini chuqur egallash','Kommunikativ qobiliyat — tinglovchi bilan muloqot bog‘lash','Vaqt va faoliyatni uyushtirish tashkilotchilikka oid','qollash'),
(7,6,'O‘qituvchi kelgusi darsda o‘quvchilarning qiyinchiligini oldindan taxmin qildi. Qaysi qobiliyat?','Pedagogik tasavvur — kelgusi holat va natijalarni bashoratlash','Didaktik qobiliyat — mavjud materialni sodda tushuntirish','Akademik qobiliyat — mavzuni ilmiy jihatdan chuqur bilish','Kommunikativ qobiliyat — muloqotdagi to‘siqlarni kamaytirish','Kelajakdagi pedagogik natijani oldindan ko‘ra bilish pedagogik tasavvurga tegishli','qollash'),
(7,7,'O‘qituvchi tushuntirar ekan, bir vaqtning o‘zida sinfni ham kuzatdi. Qaysi qobiliyat?','Diqqatni taqsimlash — bir necha jarayonni nazorat qilish','Akademik qobiliyat — bitta fan nazariyasini keng o‘rganish','Perseptiv qobiliyat — bir o‘quvchining kayfiyatini sezish','Nutq qobiliyati — talaffuz va bayonning ravonligini oshirish','Parallel faoliyatlarni kuzatish diqqatni taqsimlashga misoldir','qollash'),
(7,8,'O‘qituvchi fikrini ravon, aniq va ifodali bayon qildi. Qaysi qobiliyat?','Nutq qobiliyati — ravon va tushunarli ifodalash','Tashkilotchilik qobiliyati — sinf ishini rejalashtirish','Perseptiv qobiliyat — o‘quvchi hissiyotini anglash','Prognostik qobiliyat — kelajakdagi natijani taxminlash','Ravon ifodali bayon nutq qobiliyatiga kiradi','qollash'),
(7,9,'O‘qituvchi fanni yaxshi biladi, lekin bolalarga tushuntirib bera olmaydi. Qaysi farq yaqqol?','Akademik bilim kuchli, didaktik tushuntirish qobiliyati sust','Didaktik tushuntirish kuchli, akademik fan bilimi sust','Tashkilotchilik kuchli, kommunikativ aloqa to‘liq yo‘q','Perseptiv anglash kuchli, fan bilimi butunlay yo‘q','Bilish va bilimni boshqalarga yetkaza olish alohida jihatlardir','mulohaza'),
(7,10,'O‘quvchi darsda jim qoldi. O‘qituvchi sababini tinglab keyin yordam berdi. Nima namoyon?','Perseptiv va kommunikativ qobiliyatlarning uyg‘un qo‘llanishi','Faqat akademik va prognostik qobiliyatlarning ustunligi','Faqat ovoz balandligi va intizom boshqaruvining kuchayishi','Faqat baholash va nazorat qobiliyatlarining namoyoni','Holatni anglash va muloqot qilish birga qo‘llangan','mulohaza'),
(7,11,'Pedagogik qobiliyatlar faqat tug‘ma bo‘ladi degan fikrga munosabat qanday?','Ular kasbiy tajriba va mashq jarayonida ham rivojlantiriladi','Ular o‘qituvchilik faoliyatiga umuman aloqador emas','Ular hech qanday tajribaga javob qaytarmay doim o‘zgarmas','Ular faqat sertifikat olish bilan avtomatik shakllanadi','Pedagogik qobiliyatlarni muntazam rivojlantirish mumkin','bilish'),
(7,12,'Pedagogik qobiliyatlar ro‘yxati muallifga qarab farq qilsa, testda nima muhim?','Savolda ko‘rsatilgan muallif tasnifini aniq hisobga olish','Turli mualliflarning barcha tasniflarini bittaga tenglash','Faqat eng uzun atamani to‘g‘ri javob deb belgilash','Atamalar ta’rifini o‘qimasdan taxmin bilan tanlash','Muallifga xos tasniflar farq qilishi mumkin','mulohaza'),
(7,13,'O‘qituvchi jamoa ishini rejaladi va vazifalarni o‘rinli taqsimladi. Qaysi qobiliyat yetakchi?','Tashkilotchilik qobiliyati — guruh ishlarini uyushtirish','Akademik qobiliyat — ilmiy muammoni tekshirish','Perseptiv qobiliyat — bolaning hissiy holatini tushunish','Nutq qobiliyati — tushunchani ifodali bayon qilish','Ishni tartiblash va rollarni taqsimlash tashkilotchilikka tegishli','qollash'),
(8,1,'O‘quvchilar muammoni tahlil qilib yechim izlashdi. Qaysi ta’lim yondashuvi?','Muammoli ta’lim — masaladan yechim izlab fikrlash','Loyihaviy ta’lim — mahsulot tayyorlash bilan yakunlash','Hamkorlikdagi ta’lim — vazifani jamoa bo‘lib bajarish','O‘yinli ta’lim — o‘yin qoidalari orqali o‘rganish','Muammoli yondashuvda muammoli vaziyat fikrlashni boshlaydi','qollash'),
(8,2,'O‘quvchilar tadqiqot qilib yakunda tayyor mahsulotni taqdim etishdi. Qaysi usul?','Loyihaga asoslangan ta’lim — natijaviy mahsulot yaratish','Muammoli ta’lim — muammo ustida faqat qisqa bahs yuritish','O‘yinli ta’lim — vazifani o‘yin qoidasi orqali bajarish','Evristik ta’lim — bilimni savol orqali topishga urinish','Loyiha natijasi ko‘rinadigan mahsulot yoki yechim bo‘lishi mumkin','qollash'),
(8,3,'Har bir o‘quvchi mavzuning qismini o‘rganib, boshqalarga o‘rgatdi. Qaysi metod?','Ajurli arra — ekspert qismni o‘rganib guruhga qayta o‘rgatadi','Aqliy hujum — g‘oyalarni tez va cheklovsiz jamlaydi','Akvarium — ichki guruh muhokama qiladi, tashqi guruh kuzatadi','Keys-stadi — berilgan vaziyatni dalillar bilan tahlil qiladi','Ajurli arrada ekspert guruhi bilimini boshlang‘ich guruhga olib qaytadi','qollash'),
(8,4,'Ichki guruh muhokama qildi, tashqilar uni kuzatib fikr bildirdi. Qaysi metod?','Akvarium — kuzatuvchilar tashqi doirada tahlil qiladi','Ajurli arra — ekspertlar guruhlarga qaytib o‘rgatadi','Aqliy hujum — g‘oyalar sonini tez ko‘paytiradi','Loyihalash — tayyor mahsulotni bosqichma-bosqich yaratadi','Ichki va tashqi doira Akvarium metodining belgisi','bilish'),
(8,5,'O‘quvchilar turli ehtiyojlariga mos yordam bilan bir darsda qatnashdi. Qaysi yondashuv?','Inklyuziv ta’lim — barcha o‘quvchi uchun ishtirok imkonini yaratish','Differensial ta’lim — faqat sinfni qobiliyat bo‘yicha ajratish','Masofaviy ta’lim — faoliyatni faqat internet orqali bajarish','O‘yinli ta’lim — faoliyatni faqat musobaqaga bog‘lash','Inklyuziya barcha bolalarning mazmunli ishtirokini ko‘zlaydi','qollash'),
(8,6,'Bir xil maqsad sari o‘quvchilarga turli darajadagi vazifalar berildi. Bu nima?','Differensial ta’lim — vazifani tayyorgarlikka qarab moslashtirish','Integral ta’lim — fanlararo aloqalarni bir vazifada birlashtirish','Evristik ta’lim — javobni mustaqil izlanish bilan topish','Masofaviy ta’lim — internet orqali o‘quv resursini yetkazish','Differensial yondashuv vazifani darajaga moslashtiradi','qollash'),
(8,7,'O‘quvchilar bir masalani matematika va informatika bilan bog‘ladi. Qaysi yondashuv?','Integratsiyalashgan ta’lim — fanlararo bog‘lanishni ishlatish','Differensial ta’lim — bir fan vazifasini darajalarga ajratish','Muammoli ta’lim — savolga javobni qidirib topish','O‘yinli ta’lim — o‘rganishni qoidali faoliyatga aylantirish','Fanlararo bog‘lanish integratsiyaning belgisidir','qollash'),
(8,8,'Darsda o‘quvchi faqat tinglab o‘tirmasdan faol savol berdi va fikr almashdi. Qaysi yondashuv?','Interfaol ta’lim — o‘zaro faol muloqot va ishtirok','Masofaviy ta’lim — fazoviy ajralgan holda o‘qish','Yakka tartibda ta’lim — faqat mustaqil vazifa bajarish','Nazoratga asoslangan ta’lim — faqat natijani ballash','Interfaol o‘qitish faol muloqotga tayanadi','qollash'),
(8,9,'Loyiha darsi yakunda mahsulot bermasdan faqat bahs bilan tugadi. Qaysi baho asosli?','Loyiha bosqichlari va kutilgan natija qayta aniqlanishi kerak','Har qanday oddiy muhokama o‘z-o‘zidan to‘liq loyiha hisoblanadi','Mahsulot bo‘lmasa ham loyiha natijasini tekshirishning hojati yo‘q','Metod tanlovidan qat’i nazar hamma dars bir xil natija berishi shart','Loyihaviy faoliyat aniq natija va rejalashni talab etadi','mulohaza'),
(8,10,'Sinfdan bir bola ko‘rsatmani ko‘rishda qiynaladi. Inklyuziv yondashuvda nima qilish lozim?','Mos format va qo‘llab-quvvatlash berib, faol ishtirokni ta’minlash','Har doim barcha o‘quvchiga aynan bir xil yozuv o‘lchami berish','Bolaning ishtirokini cheklab, vazifadan butunlay ozod qilish','Muammoni aniqlamasdan, bolani doimiy ravishda chetlashtirish','Moslashtirish ishtirok imkonini oshirish uchun amalga oshiriladi','mulohaza'),
(8,11,'Ta’lim texnologiyasini tanlashda eng asosli mezon qaysi?','Maqsad, yosh, ehtiyoj va mavjud vositalarning birgalikdagi mosligi','Faqat metodning nomi yangiligi va tanish bo‘lmagan atamalari','Faqat kompyuter soni va taqdimotdagi animatsiyalar miqdori','Faqat boshqa o‘qituvchi yaqinda shu usulni qo‘llagani','Metod pedagogik maqsad va o‘quvchi imkoniyatiga mos tanlanadi','mulohaza')
 ) t(topic_order,seed_no,stem,answer,wrong_1,wrong_2,wrong_3,explanation,cognitive)
 LOOP
  SELECT l.id INTO STRICT v_lesson FROM public.lessons l JOIN public.modules m ON m.id=l.module_id WHERE m.code='M15' AND l.order_idx=r.topic_order AND l.status='published';
  SELECT c.id,c.subject_id,c.group_code INTO STRICT v_con,v_sub,v_group FROM public.constructs c WHERE c.code='PM.GEN.'||lpad(r.topic_order::text,2,'0') AND c.is_active;
  v_seed := 'm15-y1-20261018:'||r.topic_order::text||':'||r.seed_no::text;
  v_qid := md5(v_seed)::uuid;
  INSERT INTO public.questions (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id,is_generated)
  VALUES(v_qid,v_sub,v_con,v_group,'Y1'::public.question_format,r.cognitive::public.cognitive_level,3,r.stem,'review'::public.content_status,'authored:m15-topictest-20261018:'||r.topic_order::text||':'||r.seed_no::text,v_lesson,false)
  ON CONFLICT (id) DO NOTHING;
  v_choices := ARRAY[r.answer,r.wrong_1,r.wrong_2,r.wrong_3];
  FOR v_n IN 1..4 LOOP
    v_oid := md5(v_seed||':option:'||v_n::text)::uuid;
    INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_oid,v_qid,'a',v_n,v_choices[v_n]) ON CONFLICT(id) DO NOTHING;
  END LOOP;
  INSERT INTO public.question_keys(question_id,payload,explanation_md)
  VALUES(v_qid,jsonb_build_object('correct_option_id',md5(v_seed||':option:1')::uuid),r.explanation)
  ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END
$m15$;
COMMIT;